// The critical results log  (permissions: diagnostics.critical.view)
export const listCritical = () =>
  api("GET", `/critical-results`, undefined);   // api(): see get_guide('envelope-and-errors')

// A critical result with who was told  (permissions: diagnostics.critical.view)
export const getCritical = (critical_result_id) =>
  api("GET", `/critical-results/${critical_result_id}`, undefined);   // api(): see get_guide('envelope-and-errors')

// Record who was told the critical result  (permissions: diagnostics.critical.communicate)
export const communicate = (critical_result_id, body) =>
  api("POST", `/critical-results/${critical_result_id}/communications`, body, { idempotent: true });   // api(): see get_guide('envelope-and-errors')

// Diagnostic services work waiting  (permissions: diagnostics.critical.view, diagnostics.quality.view)
export const diagnosticsWorklist = () =>
  api("GET", `/diagnostics/worklist`, undefined);   // api(): see get_guide('envelope-and-errors')
